INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (83, 114, 'BOPP cigarette tobacco pack wrapping film (plain/shrinkage)', '../upload/image/20180922/20180922163557_67348.jpg', '<p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>BOPP cigarette tobacco pack wrapping film (plain/shrinkage)</strong></span></p> <p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">POLYPROPILENE FILM</span></p> <p><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1-POLYPROPILENE B, width:118</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Inner diameter:76, outer:350 max,Thickness: 18 μ</span></p> <p><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2-POLYPROPILENE B, width:136</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Inner diameter:76,Outer:350 max,Thickness: 18 μ</span></p> <p><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">3-POLYPROPILENE B, width:345</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Inner diameter:76, Outer:350max,Thickness: 23 μ</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">FOR USAGE IN NAKEDWRAP PRODUCTION</span></p> <p><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">4-POLYPROPILENE B, width:355</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Inner diameter:76,Outer:350 max,Thickness: 23 μ</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">FOR USAGE IN NAKEDWRAP PRODUCTION</span></p> <p><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> TEAR TAPE</span></p> <p><br/></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1-P 1-POLYPROPYLENE SELF-ADHESIVE TEAR TAPE; Width: 2mm</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Thickness: 26μm;Length: 50.000mt</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Print: 2mm HOLOGRAPHIC " QUALITY BLEND''''</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Print Base Color: METALIC GOLD</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> " LEFT HAND EDGE LEADING "</span></p> <p><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2-TEAR TAPE Width: 1,6mm</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Thickness: 32μm Length: 75.000mt</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> TRANSPARENT</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"> " LEFT HAND EDGE LEADING "</span></p> <p><br/></p><br/> <p><br/></p> <p><span><br/> </span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (83, 127, 'Half-shrinkage BOPP Cigarette Film with heat sealable matches high-speed packaging machines.', '../upload/image/20180925/20180925223916_91120.jpg', '<p></p><p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>BOPP Shrinkage Cigarette Film For Hard/Soft Tobacco Pack</strong></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPP cigarette packaging film is one of the most important series of BOPP film , which also festures the high-class quality .</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> They were divided three items as :</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 1.Plain BOPP Cigarette Film with heat sealable matches slow/plain-speed packaging machines.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 2.Half-shrinkage BOPP Cigarette Film with heat sealable matches high-speed packaging machines.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 3.High-shrinkage BOPP Cigarette Film with heat sealable matches high-speed packaging machines.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> They are featuring high transparency, low haze and low static electricity.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> It has the property of superior low temperature heat sealability and high stiffness,transparency as well as slipping, and it is designed for the various kinds of cigarette packaging machine, and it is used for the cigarette hard/soft unit packs or long packs which 