INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (83, 129, 'High-shrinkage BOPP Cigarette Film with heat sealable matches high-speed packaging machines.', '../upload/image/20180925/20180925223904_77332.jpg', '<p><span style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span dingbats="" style="color: rgb(229, 51, 51); line-height: 36px; font-family: Tahoma; font-size: 18px;" zapf=""><strong>a.) BOPP cigarette tobacco film generally used for soft/hard tobacco pack and used for modern high/slow packing machines.</strong></span> <p style="text-indent:0px;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span dingbats="" style="color: rgb(229, 51, 51); line-height: 36px; font-family: Tahoma; font-size: 18px;" zapf="">transparent biaxially oriented polypropylene cigarette film featured coextruded heat sealable on both sides,incorporated with anti- static protection </span><br/> <span dingbats="" style="line-height: 36px; font-family: Calibri,;" zapf=""><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Thickness : 18,19,20,</span><strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;text-decoration:underline;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;background-color:#FFFF00;">21,22</span></span></strong><span style="color:#E53333;font-family:Tahoma;font-size:18px;">,25 Microns </span></span><br/> <span dingbats="" style="line-height: 36px; font-family: Calibri,;" zapf=""><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Width: 90,110,118,120,135,150,220,350MM Length:2000M,</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;background-color:#FFFF00;">2800M,3000M</span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">,3500M </span></span><br/> <span dingbats="" style="color: rgb(229, 51, 51); line-height: 36px; font-family: Tahoma; font-size: 18px;" zapf=""