t-family: Tahoma; font-size: 18px;" zapf="">22Microns*118mm*2800M </span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span dingbats="" style="color: rgb(229, 51, 51); font-family: Tahoma; font-size: 18px;" zapf="">22Microns*120mm*2800M</span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span dingbats="" style="color: rgb(229, 51, 51); font-family: Tahoma; font-size: 18px;" zapf="">22Microns*125mm*2800M</span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span dingbats="" style="color: rgb(229, 51, 51); font-family: Tahoma; font-size: 18px;" zapf=""><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">22Microns*130mm*2800M </span> </span> </span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span dingbats="" style="color: rgb(229, 51, 51); font-family: Tahoma; font-size: 18px;" zapf="">22Microns*135mm*2800M </span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span dingbats="" style="color: rgb(229, 51, 51); font-family: Tahoma; font-size: 18px;" zapf="">22Microns*225mm*2800M </span></p> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span dingbats="" style="color: rgb(229, 51, 51); font-family: Tahoma; font-size: 18px;" zapf="">22Microns*350mm*2800M</span></p> <p style="color:#3A3A3A;text-in